    /// making a fresh one. `dst` is cleared first, so it is empty on
    /// every error path as well as when the call finds nothing.
    pub fn set_recipe_into(&self, dst: &mut Vec<ItemWithQualityCount>, recipe: Option<&Value>, quality: Option<Object>) -> Result<(), Status> {
        dst.clear();
        let _mark = AllocMark::new();
        let mut a = [0u8; 32];
        let mut r = [0u8; 8];
        if let Some(v) = recipe {
            a[0] = 1;
            write_dyn(&mut a[8..], v);
        }
        if let Some(v) = quality {
            a[24] = 1;
            wr_u32(&mut a[..], 28, v.0);
        }
        let st = unsafe { fk_call(self.0.0, 644, a.as_ptr() as u32, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let out = &mut *dst;
        out.reserve(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 20) as *const u8, 20) };
            out.push(ItemWithQualityCount::decode_at(&d[0..]));
        }
        Ok(())
    }

    /// Revives a ghost silently, so the revival makes no sound and no smoke is
    /// created.
    pub fn silent_revive(&self, args: LuaEntitySilentReviveArgs) -> Result<(Vec<ItemWithQualityCount>, Option<Object>, Option<Object>), Status> {
        let _mark = AllocMark::new();
        let mut a = [0u8; 8];
        let mut r = [0u8; 24];
        args.encode_at(&mut a[0..]);
        let st = unsafe { fk_call(self.0.0, 645, a.as_ptr() as u32, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let mut v0 = Vec::with_capacity(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 20) as *const u8, 20) };
            v0.push(ItemWithQualityCount::decode_at(&d[0..]));
        }
        let mut v1: Option<Object> = None;
        if r[8] != 0 {
            v1 = Some(Object(rd_u32(&r[..], 12)));
        }
        let mut v2: Option<Object> = None;
        if r[16] != 0 {
            v2 = Some(Object(rd_u32(&r[..], 20)));
        }
        Ok((v0, v1, v2))
    }

