    /// Items this ghost will request when revived or items this item request
    /// proxy is requesting.
    pub fn item_requests(&self) -> Result<Vec<ItemWithQualityCount>, Status> {
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 844, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let mut v0 = Vec::with_capacity(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 20) as *const u8, 20) };
            v0.push(ItemWithQualityCount::decode_at(&d[0..]));
        }
        Ok(v0)
    }

    /// Items this ghost will request when revived or items this item request
    /// proxy is requesting.
    /// `item_requests` writing into `dst`, reusing its allocation rather than
    /// making a fresh one. `dst` is cleared first, so it is empty on
    /// every error path as well as when the call finds nothing.
    pub fn item_requests_into(&self, dst: &mut Vec<ItemWithQualityCount>) -> Result<(), Status> {
        dst.clear();
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 844, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let out = &mut *dst;
        out.reserve(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 20) as *const u8, 20) };
            out.push(ItemWithQualityCount::decode_at(&d[0..]));
        }
        Ok(())
    }

