/// A handle to a `LuaEquipmentGridPrototype`.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct LuaEquipmentGridPrototype(pub Object);

impl LuaEquipmentGridPrototype {
    /// Equipment category names for the [categories] that may be inserted into
    /// this equipment grid.
    pub fn equipment_categories(&self) -> Result<Vec<LuaStr>, Status> {
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 1477, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let mut v0 = Vec::with_capacity(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 8) as *const u8, 8) };
            v0.push(get_str(&d[..], 0));
        }
        Ok(v0)
    }

    /// Equipment category names for the [categories] that may be inserted into
    /// this equipment grid.
    /// `equipment_categories` writing into `dst`, reusing its allocation rather than
    /// making a fresh one. `dst` is cleared first, so it is empty on
    /// every error path as well as when the call finds nothing.
    pub fn equipment_categories_into(&self, dst: &mut Vec<LuaStr>) -> Result<(), Status> {
        dst.clear();
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 1477, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let out = &mut *dst;
        out.reserve(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 8) as *const u8, 8) };
            out.push(get_str(&d[..], 0));
        }
        Ok(())
    }

    pub fn height(&self) -> Result<u32, Status> {
        let mut r = [0u8; 4];
        let st = unsafe { fk_call(self.0.0, 1478, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = u32::from_le_bytes(r[0..4].try_into().unwrap());
        Ok(v0)
    }

    /// If the player can move equipment into or out of this grid.
    pub fn locked(&self) -> Result<bool, Status> {
        let mut r = [0u8; 1];
        let st = unsafe { fk_call(self.0.0, 1479, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = r[0] != 0;
        Ok(v0)
    }

    /// The class name of this object.
    pub fn object_name(&self) -> Result<LuaStr, Status> {
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 1480, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = get_str(&r[..], 0);
        Ok(v0)
    }

    /// The class name of this object.
    pub fn object_name_is(&self, want: &str) -> Result<bool, Status> {
        let mut a = [0u8; 8];
        let mut r = [0u8; 1];
        put_str(&mut a[..], 0, want.as_bytes());
        let st = unsafe { fk_call(self.0.0, 1481, a.as_ptr() as u32, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = r[0] != 0;
        Ok(v0)
    }

    /// Is this object valid?
    pub fn valid(&self) -> Result<bool, Status> {
        let mut r = [0u8; 1];
        let st = unsafe { fk_call(self.0.0, 1482, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = r[0] != 0;
        Ok(v0)
    }

    pub fn width(&self) -> Result<u32, Status> {
        let mut r = [0u8; 4];
        let st = unsafe { fk_call(self.0.0, 1483, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = u32::from_le_bytes(r[0..4].try_into().unwrap());
        Ok(v0)
    }

}

