/// Reads LuaRenderObject::angle off every handle in objs in ONE host call, writing
/// element i to dst[i] and returning how many it READ. dst must be at
/// least objs.len() long, and objs is a &[Object] because that is what a
/// search returns; see fk_bulk_get for when an element is skipped.
pub fn lua_render_object_angle_bulk(objs: &[Object], dst: &mut [f32]) -> Result<usize, Status> {
    if objs.is_empty() {
        return Ok(0);
    }
    if dst.len() < objs.len() {
        return Err(Status(Status::BAD_ARGS));
    }
    let st = unsafe {
        fk_bulk_get(3243, objs.as_ptr() as u32, objs.len() as u32,
            dst.as_mut_ptr() as u32, core::ptr::addr_of_mut!(BULK_READ) as u32)
    };
    if st != 0 {
        return Err(Status(st));
    }
    Ok(unsafe { BULK_READ } as usize)
}


