/// A handle to a `LuaTerritory`.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct LuaTerritory(pub Object);

impl LuaTerritory {
    /// Immediately destroys the territory, along with any segmented units
    /// guarding it.
    pub fn destroy(&self) -> Result<(), Status> {
        let st = unsafe { fk_call(self.0.0, 4000, 0, 0) };
        if st != 0 {
            return Err(Status(st));
        }
        Ok(())
    }

    /// Gets all chunks that are a part of the territory.
    pub fn get_chunks(&self) -> Result<Vec<ChunkPositionAndArea>, Status> {
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 4001, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let mut v0 = Vec::with_capacity(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 48) as *const u8, 48) };
            v0.push(ChunkPositionAndArea::decode_at(&d[0..]));
        }
        Ok(v0)
    }

    /// Gets all chunks that are a part of the territory.
    /// `get_chunks` writing into `dst`, reusing its allocation rather than
    /// making a fresh one. `dst` is cleared first, so it is empty on
    /// every error path as well as when the call finds nothing.
    pub fn get_chunks_into(&self, dst: &mut Vec<ChunkPositionAndArea>) -> Result<(), Status> {
        dst.clear();
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 4001, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let out = &mut *dst;
        out.reserve(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 48) as *const u8, 48) };
            out.push(ChunkPositionAndArea::decode_at(&d[0..]));
        }
        Ok(())
    }

    /// Get the path that the territory's units follow when patrolling the
    /// territory.
    pub fn get_patrol_path(&self) -> Result<Vec<MapPosition>, Status> {
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 4002, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let mut v0 = Vec::with_capacity(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 16) as *const u8, 16) };
            v0.push(MapPosition::decode_at(&d[0..]));
        }
        Ok(v0)
    }

    /// Get the path that the territory's units follow when patrolling the
    /// territory.
    /// `get_patrol_path` writing into `dst`, reusing its allocation rather than
    /// making a fresh one. `dst` is cleared first, so it is empty on
    /// every error path as well as when the call finds nothing.
    pub fn get_patrol_path_into(&self, dst: &mut Vec<MapPosition>) -> Result<(), Status> {
        dst.clear();
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 4002, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let out = &mut *dst;
        out.reserve(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 16) as *const u8, 16) };
            out.push(MapPosition::decode_at(&d[0..]));
        }
        Ok(())
    }

    /// Gets the [LuaSegmentedUnit]s that guard this territory.
    pub fn get_segmented_units(&self) -> Result<Vec<Object>, Status> {
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 4003, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let mut v0 = Vec::with_capacity(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 4) as *const u8, 4) };
            v0.push(Object(rd_u32(&d[..], 0)));
        }
        Ok(v0)
    }

    /// Gets the [LuaSegmentedUnit]s that guard this territory.
    /// `get_segmented_units` writing into `dst`, reusing its allocation rather than
    /// making a fresh one. `dst` is cleared first, so it is empty on
    /// every error path as well as when the call finds nothing.
    pub fn get_segmented_units_into(&self, dst: &mut Vec<Object>) -> Result<(), Status> {
        dst.clear();
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 4003, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let base0 = rd_u32(&r[..], 0) as usize;
        let n0 = rd_u32(&r[..], 4) as usize;
        let out = &mut *dst;
        out.reserve(n0);
        for i in 0..n0 {
            let d = unsafe { core::slice::from_raw_parts((base0 + i * 4) as *const u8, 4) };
            out.push(Object(rd_u32(&d[..], 0)));
        }
        Ok(())
    }

    /// Regenerates the patrol path for the territory according to the game's
    /// default territory generation algorithm and overwrites the territory's
    /// current patrol path.
    pub fn regenerate_patrol_path(&self) -> Result<(), Status> {
        let st = unsafe { fk_call(self.0.0, 4004, 0, 0) };
        if st != 0 {
            return Err(Status(st));
        }
        Ok(())
    }

    /// Regenerates any segmented units that were created when the territory was
    /// generated by the map generator.
    pub fn regenerate_segmented_units(&self) -> Result<(), Status> {
        let st = unsafe { fk_call(self.0.0, 4005, 0, 0) };
        if st != 0 {
            return Err(Status(st));
        }
        Ok(())
    }

    /// Overwrite the territory patrol path for units that guard the territory.
    pub fn set_patrol_path(&self, patrol_path: &[MapPosition]) -> Result<(), Status> {
        let _mark = AllocMark::new();
        let mut a = [0u8; 8];
        let ppatrol_path = galloc((patrol_path.len() * 16) as u32);
        for (i, e) in patrol_path.iter().enumerate() {
            let d = unsafe { core::slice::from_raw_parts_mut((ppatrol_path as usize + i * 16) as *mut u8, 16) };
            e.encode_at(&mut d[0..]);
        }
        wr_u32(&mut a[..], 0, ppatrol_path);
        wr_u32(&mut a[..], 4, patrol_path.len() as u32);
        let st = unsafe { fk_call(self.0.0, 4006, a.as_ptr() as u32, 0) };
        if st != 0 {
            return Err(Status(st));
        }
        Ok(())
    }

    /// The class name of this object.
    pub fn object_name(&self) -> Result<LuaStr, Status> {
        let _mark = AllocMark::new();
        let mut r = [0u8; 8];
        let st = unsafe { fk_call(self.0.0, 4007, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = get_str(&r[..], 0);
        Ok(v0)
    }

    /// The class name of this object.
    pub fn object_name_is(&self, want: &str) -> Result<bool, Status> {
        let mut a = [0u8; 8];
        let mut r = [0u8; 1];
        put_str(&mut a[..], 0, want.as_bytes());
        let st = unsafe { fk_call(self.0.0, 4008, a.as_ptr() as u32, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = r[0] != 0;
        Ok(v0)
    }

    /// The surface on which this territory is located.
    pub fn surface(&self) -> Result<Object, Status> {
        let mut r = [0u8; 4];
        let st = unsafe { fk_call(self.0.0, 4009, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = Object(rd_u32(&r[..], 0));
        Ok(v0)
    }

    /// Is this object valid?
    pub fn valid(&self) -> Result<bool, Status> {
        let mut r = [0u8; 1];
        let st = unsafe { fk_call(self.0.0, 4010, 0, r.as_mut_ptr() as u32) };
        if st != 0 {
            return Err(Status(st));
        }
        let v0 = r[0] != 0;
        Ok(v0)
    }

}

