const _: () = assert!(core::mem::size_of::<BulkOptU32>() == 8);


/// One element of a bulk read of an OPTIONAL attribute: the getter's own
/// return block, which carries a presence byte because the description
/// says the value may not be there. `has` false means the API said
/// nothing, or that this element could not be read at all -- the count
/// the bulk call returns is what tells the two apart in aggregate.
#[derive(Copy, Clone, Debug, Default)]
#[repr(C)]
pub struct BulkOptU64 {
    pub has: bool,
    _pad: [u8; 3],
    pub lo: u32,
    pub hi: u32,
}

impl BulkOptU64 {
    /// The value, reassembled from the two halves the wire carries.
    pub fn v(&self) -> u64 { ((self.hi as u64) << 32) | self.lo as u64 }
}

const _: () = assert!(core::mem::size_of::<BulkOptU64>() == 12);


